function structureExport(structure){return {...contextExport("tensor-gate-lens/structure/v1"),structure:{id:structure.id,kind:structure.kind,title:structure.title,definition:structure.definition,score:structure.score,members:structure.members.map(i=>({index:i,id:id(i)}))}};}
