function basketExport(){const data=basketData();return {...contextExport("tensor-gate-lens/basket/v1"),selectedGates:data.indices.map(gateExport),partialTensor:{symbol:"S",definition:"exact sum of selected gates",nonzeroCoordinates:[...data.tensor].map(([key,value])=>({...indexRecord(key,state.analysis.n),coefficient:ascii(value)}))},remainingTensor:{symbol:"T-S",definition:"exact target tensor minus selected partial tensor; equals the sum of unselected certificate gates"},flatteningRanks:{A:data.ranks[0],B:data.ranks[1],C:data.ranks[2],maximumLowerBound:data.lower,definition:"Each matrix flattening rank is a lower bound on tensor rank."},verdict:data.verdict,boundary:data.boundary};}
function constructionExport(){const a=state.analysis;return {...contextExport("tensor-gate-lens/construction/v1"),gates:Array.from({length:a.r},(_,i)=>gateExport(i)),target:[...a.target].sort().map(key=>({...indexRecord(key,a.n),coefficient:"1"}))};}
function workbenchExportChunks(){const a=state.analysis,order=orderIndices(),context=contextExport("tensor-gate-lens/workbench/v1"),prefix={...context,metric:{mode:state.mode,definition:els["metric-definition"].textContent},controls:{edgeFilter:state.edgeFilter,hideEmpty:state.hideEmpty,upperTriangle:state.upper,view:state.view},ordering:{heuristic:state.order,definition:els["order-definition"].textContent,displayOrder:order.map(i=>({index:i,id:id(i)}))}};function* chunks(){yield `${JSON.stringify(prefix).slice(0,-1)},\"gates\":[`;for(let i=0;i<a.r;i++){if(i)yield ",";yield JSON.stringify(gateExport(i));}yield `],\"edges\":[`;let first=true;for(let i=0;i<a.r;i++)for(let j=i+1;j<a.r;j++){const info=a.pairs[i][j];if(!info.adjacent)continue;if(!first)yield ",";first=false;yield JSON.stringify({source:{index:i,id:id(i)},target:{index:j,id:id(j)},cancellationCount:info.cancel,reinforcementCount:info.reinforce,weighted:ascii(info.weighted),cancelWeight:ascii(info.cancelWeight),reinforceWeight:ascii(info.reinforceWeight),sharedUnwantedCoordinates:info.coordinates.map(x=>({...indexRecord(x.key,a.n),coefficients:[ascii(x.a),ascii(x.b)],product:ascii(x.product),kind:x.kind}))});}const tail={components:a.components.map(members=>members.map(i=>({index:i,id:id(i)}))),isolates:a.isolates.map(i=>({index:i,id:id(i)})),pureTarget:a.pure.map(i=>({index:i,id:id(i)})),structures:a.structures.map(s=>structureExport(s).structure),basket:dataForSelection()};yield `],${JSON.stringify(tail).slice(1)}`;}return chunks();}
async function exportRequest(path,token,body){const headers={};if(token)headers["X-Proofs-Viz-Export-Token"]=token;if(body!==undefined)headers["Content-Type"]="application/octet-stream";const response=await fetch(path,{method:"POST",headers,body});if(!response.ok)throw new Error((await response.text()).trim()||`HTTP ${response.status}`);return response;}
async function saveWorkbench(){const button=els["copy-workbench"],encoder=new TextEncoder();let token;button.disabled=true;copyFeedback("Saving workbench JSON…",true,0);try{const start=await fetch("/api/export/workbench/start",{method:"POST",headers:{"X-Proofs-Viz-Construction":state.analysis.c.id}});if(!start.ok)throw new Error((await start.text()).trim()||`HTTP ${start.status}`);token=(await start.json()).token;for(const text of workbenchExportChunks()){const bytes=encoder.encode(text),chunkSize=256*1024;for(let offset=0;offset<bytes.length;offset+=chunkSize)await exportRequest("/api/export/workbench/chunk",token,bytes.subarray(offset,offset+chunkSize));await new Promise(resolve=>setTimeout(resolve,0));}const response=await exportRequest("/api/export/workbench/finish",token);const result=await response.json();token=undefined;copyFeedback(`Workbench JSON saved to ${result.path} (${Number(result.bytes).toLocaleString()} bytes).`,true,0);}catch(error){if(token)try{await exportRequest("/api/export/workbench/cancel",token);}catch{}copyFeedback(`Workbench save failed: ${error.message}`,false,8000);}finally{button.disabled=false;}}
function dataForSelection(){return {members:[...state.basket].sort((a,b)=>a-b).map(i=>({index:i,id:id(i)})),highlight:[...state.highlight].sort((a,b)=>a-b).map(i=>({index:i,id:id(i)}))};}
function auditExport(){const a=state.analysis,indices=selectedAudit(),tensor=sumGateTensors(a.tensors,indices);return {...contextExport("tensor-gate-lens/audit/v1"),selectedGates:indices.map(i=>({index:i,id:id(i)})),sum:{nonzeroCoordinates:[...tensor].map(([key,value])=>({...indexRecord(key,a.n),coefficient:ascii(value)}))},targetComparison:{desiredAtOne:[...a.target].filter(key=>one(tensor.get(key)||rat(0))).length,totalDesired:a.target.size,liveUnwanted:[...tensor].filter(([key])=>!a.target.has(key)).length}};}
function safeJSON(value){return JSON.stringify(value,null,2);}
function copyFeedback(message,ok,hideAfter=3500){els["copy-status"].textContent=message;els["copy-status"].className=`copy-status show ${ok?"success":"failure"}`;clearTimeout(state.copyTimer);if(hideAfter>0)state.copyTimer=setTimeout(()=>{els["copy-status"].className="copy-status";},hideAfter);}
async function copyText(value,label){const payload=safeJSON(value);try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(payload);else{const area=document.createElement("textarea");area.value=payload;area.setAttribute("readonly","");area.style.position="fixed";area.style.opacity="0";document.body.append(area);area.select();const ok=document.execCommand("copy");area.remove();if(!ok)throw new Error("browser rejected fallback copy command");}copyFeedback(`${label} copied (${payload.length.toLocaleString()} characters).`,true);}catch(error){copyFeedback(`${label} copy failed: ${error.message}`,false);}}

els.dimension.addEventListener("change",()=>{state.dimension=Number(els.dimension.value);selectConstruction(constructions[state.dimension][0].id);});
els.construction.addEventListener("change",()=>selectConstruction(els.construction.value));
els.gates.addEventListener("change",renderAudit);
document.querySelector("#all").addEventListener("click",()=>setAll(true));document.querySelector("#none").addEventListener("click",()=>setAll(false));
document.querySelectorAll(".filter").forEach(button=>button.addEventListener("click",()=>{state.auditFilter=button.dataset.filter;document.querySelectorAll(".filter").forEach(x=>x.classList.toggle("active",x===button));renderAudit();}));
function choosePair(i,j){if(i===j)return;state.pair=[i,j];renderPair();document.querySelectorAll(".interaction-cell.selected").forEach(cell=>cell.classList.remove("selected"));document.querySelectorAll("[data-i][data-j]").forEach(cell=>{const x=Number(cell.dataset.i),y=Number(cell.dataset.j);if((x===i&&y===j)||(x===j&&y===i))cell.classList.add("selected");});}
els["interaction-grid"].addEventListener("click",event=>{const cell=event.target.closest("[data-i][data-j]");if(cell&&!cell.disabled)choosePair(Number(cell.dataset.i),Number(cell.dataset.j));});
els["interaction-grid"].addEventListener("dblclick",event=>{const label=event.target.closest("[data-gate-label]");if(label){state.basket.add(Number(label.dataset.gateLabel));renderInteraction();return;}const cell=event.target.closest("[data-i][data-j]");if(cell&&!cell.disabled){state.basket.add(Number(cell.dataset.i));state.basket.add(Number(cell.dataset.j));renderInteraction();}});
els["interaction-grid"].addEventListener("mouseover",event=>{const label=event.target.closest("[data-gate-label]"),cell=event.target.closest("[data-i][data-j]");if(label)setFocus(Number(label.dataset.gateLabel));else if(cell)setFocus(Number(cell.dataset.i));});
els["interaction-grid"].addEventListener("mouseleave",()=>setFocus(null));
els["interaction-grid"].addEventListener("focusin",event=>{const label=event.target.closest("[data-gate-label]"),cell=event.target.closest("[data-i][data-j]");if(label)setFocus(Number(label.dataset.gateLabel));else if(cell)setFocus(Number(cell.dataset.i));});
els["interaction-grid"].addEventListener("focusout",event=>{if(!els["interaction-grid"].contains(event.relatedTarget))setFocus(null);});
els["interaction-grid"].addEventListener("keydown",event=>{const label=event.target.closest("[data-gate-label]");if(label&&(event.key==="Enter"||event.key===" ")){event.preventDefault();state.basket.add(Number(label.dataset.gateLabel));renderInteraction();}});
els["interaction-graph"].addEventListener("click",event=>{const edge=event.target.closest("[data-edge-i]");if(edge)choosePair(Number(edge.dataset.edgeI),Number(edge.dataset.edgeJ));});
els["interaction-graph"].addEventListener("dblclick",event=>{const node=event.target.closest("[data-node]");if(node){state.basket.add(Number(node.dataset.node));renderInteraction();return;}const edge=event.target.closest("[data-edge-i]");if(edge){state.basket.add(Number(edge.dataset.edgeI));state.basket.add(Number(edge.dataset.edgeJ));renderInteraction();}});
els["interaction-graph"].addEventListener("mouseover",event=>{const node=event.target.closest("[data-node]");if(node)setFocus(Number(node.dataset.node));});els["interaction-graph"].addEventListener("mouseleave",()=>setFocus(null));els["interaction-graph"].addEventListener("focusin",event=>{const node=event.target.closest("[data-node]");if(node)setFocus(Number(node.dataset.node));});els["interaction-graph"].addEventListener("keydown",event=>{const node=event.target.closest("[data-node]");if(node&&(event.key==="Enter"||event.key===" ")){event.preventDefault();state.basket.add(Number(node.dataset.node));renderInteraction();}});
els["add-pair"].addEventListener("click",()=>{if(!state.pair)return;state.pair.forEach(i=>state.basket.add(i));renderInteraction();});
els["clear-basket"].addEventListener("click",()=>{state.basket.clear();renderInteraction();});els["basket-gates"].addEventListener("click",event=>{const button=event.target.closest("[data-remove]");if(!button)return;state.basket.delete(Number(button.dataset.remove));renderInteraction();});
els["interaction-mode"].addEventListener("change",()=>{state.mode=els["interaction-mode"].value;renderInteraction();});els["gate-order"].addEventListener("change",()=>{state.order=els["gate-order"].value;renderInteraction();});els["edge-filter"].addEventListener("change",()=>{state.edgeFilter=els["edge-filter"].value;renderInteraction();});els["interaction-view"].addEventListener("change",()=>{state.view=els["interaction-view"].value;renderInteraction();});els["hide-empty"].addEventListener("change",()=>{state.hideEmpty=els["hide-empty"].checked;renderInteraction();});els["upper-triangle"].addEventListener("change",()=>{state.upper=els["upper-triangle"].checked;renderInteraction();});
els["structures-list"].addEventListener("click",event=>{const button=event.target.closest("[data-structure-action]");if(!button)return;const structure=state.analysis.structures.find(x=>x.id===button.dataset.structure);if(!structure)return;const action=button.dataset.structureAction;if(action==="highlight"){state.highlight=new Set(structure.members);state.highlightID=structure.id;renderInteraction();}else if(action==="add"){structure.members.forEach(i=>state.basket.add(i));renderInteraction();}else if(action==="replace"){state.basket=new Set(structure.members);renderInteraction();}else copyText(structureExport(structure),`${structure.title} JSON`);});
els["clear-highlight"].addEventListener("click",()=>{state.highlight.clear();state.highlightID=null;renderInteraction();});
els["copy-workbench"].addEventListener("click",saveWorkbench);els["copy-pair"].addEventListener("click",()=>copyText(pairExport(),"Pair JSON"));els["copy-basket"].addEventListener("click",()=>copyText(basketExport(),"Basket JSON"));els["copy-construction"].addEventListener("click",()=>copyText(constructionExport(),"Construction JSON"));els["copy-audit"].addEventListener("click",()=>copyText(auditExport(),"Audit JSON"));

const importSpecs=[
  {file:"laderman.json",id:"laderman",label:"Laderman",n:3,source:"Programs/BilinearComplexity/laderman_matrices.sage"},
  {file:"smirnov-1.json",id:"smirnov-1",label:"Chokaev–Shumkin / Smirnov-1",n:3,source:"Programs/BilinearComplexity/smirnov2018_matrices.sage"},
  {file:"smirnov-2.json",id:"smirnov-2",label:"Chokaev–Shumkin / Smirnov-2",n:3,source:"Programs/BilinearComplexity/smirnov2018_matrices.sage"},
  {file:"strassen-squared.json",id:"strassen-squared",label:"Strassen squared",n:4},
  {file:"rational-48.json",id:"rational-48",label:"Moran–Schwartz–Yuan rational rank-48",n:4}
];
Promise.all(importSpecs.map(imported)).then(xs=>{for(const construction of xs)constructions[construction.n].push(construction);state.construction=constructions[2][0];state.analysis=analyzeConstruction();renderControls();render();}).catch(error=>{document.body.prepend(Object.assign(document.createElement("pre"),{className:"load-error",textContent:`Could not load construction data: ${error.message}`}));});
